package com.sliit.smartlibrary.dto;
public class BookRequest { private Long id; private String title; private String isbn; private Long categoryId; private Long authorId; private Long publisherId; private String description; private Integer publishedYear; private String coverUrl; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getTitle(){return title;} public void setTitle(String title){this.title=title;} public String getIsbn(){return isbn;} public void setIsbn(String isbn){this.isbn=isbn;} public Long getCategoryId(){return categoryId;} public void setCategoryId(Long categoryId){this.categoryId=categoryId;} public Long getAuthorId(){return authorId;} public void setAuthorId(Long authorId){this.authorId=authorId;} public Long getPublisherId(){return publisherId;} public void setPublisherId(Long publisherId){this.publisherId=publisherId;} public String getDescription(){return description;} public void setDescription(String description){this.description=description;} public Integer getPublishedYear(){return publishedYear;} public void setPublishedYear(Integer publishedYear){this.publishedYear=publishedYear;} public String getCoverUrl(){return coverUrl;} public void setCoverUrl(String coverUrl){this.coverUrl=coverUrl;} }
